<template><view class="page"><view v-if="error" class="error">{{error}}<button class="button outline" @tap="load">重新加载</button></view><template v-if="task"><view v-if="task.result"><video id="lesson-video" class="video" :src="mediaUrl(task.result.video)" :poster="mediaUrl(task.result.cover)" controls show-center-play-btn/><view class="section-title">{{task.result.title}}</view><view class="muted small">{{task.result.disclosure}}</view><view class="answer">{{task.result.answer}}</view><view v-for="(step,i) in task.result.steps" :key="i" class="row" @tap="seek(i)"><view class="row-title">{{i+1}}　{{step.title}}</view><view class="muted small">{{step.description}}</view></view><button class="button" @tap="capture">再拍一道题</button></view><view v-else><view class="question">{{task.title}}</view><view v-if="['queued','running'].includes(task.status)"><view v-for="(step,i) in stages" :key="step.key" class="step" :class="{done:current>i,active:current===i}"><text class="dot">{{current>i?'✓':i+1}}</text><view>{{step.title}}<view class="muted small">{{current>i?'已完成':current===i?'正在进行':'等待中'}}</view></view></view><view class="section-title">{{stageTitle}}</view><view class="muted small">可以离开页面，稍后在视频中查看</view><button class="button" @tap="history">查看我的视频</button><button class="button outline" @tap="cancel">取消本次生成</button></view><view v-else class="notice">{{task.status==='cancelled'?'任务已取消':errorText(task.error)}}<button class="button" @tap="capture">重新拍题</button></view></view></template></view></template>
<script setup>
import {ref,computed} from 'vue';import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';import {request,mediaUrl,errorText} from '../../lib/api';
const task=ref(null),error=ref('');let id='',timer=null,visible=false;const stages=[{key:'recognizing',title:'识别题目'},{key:'solving',title:'分析解法'},{key:'rendering',title:'制作视频'},{key:'completed',title:'完成'}];const current=computed(()=>task.value?.stage==='queued'?0:['checking','voicing','rendering'].includes(task.value?.stage)?2:Math.max(0,stages.findIndex(s=>s.key===task.value?.stage)));const stageTitle=computed(()=>['checking','voicing','rendering'].includes(task.value?.stage)?'正在制作视频':'正在分析题目');
async function load(){clearTimeout(timer);try{task.value=await request('/api/tasks/'+id);error.value='';if(visible&&['queued','running'].includes(task.value.status))timer=setTimeout(load,2500);}catch(e){error.value=e.message;}}
onLoad(q=>{id=q.id||'';});onShow(()=>{visible=true;load();});onHide(()=>{visible=false;clearTimeout(timer);});onUnload(()=>{visible=false;clearTimeout(timer);});
async function cancel(){try{await request('/api/tasks/'+id+'/cancel',{method:'POST'});await load();}catch(e){error.value=e.message;}}
function seek(i){const segment=task.value.result.segments?.[i+1];if(segment)uni.createVideoContext('lesson-video').seek(segment.at);}
const capture=()=>uni.switchTab({url:'/pages/capture/index'}),history=()=>uni.switchTab({url:'/pages/videos/index'});
</script>
<style scoped>.video{width:100%;height:380rpx;border-radius:16rpx;background:#182b25}.question{padding:50rpx 28rpx;background:#f4f7f5;border-radius:16rpx;font-size:38rpx;margin-bottom:44rpx}.step{display:flex;align-items:flex-start;gap:24rpx;padding:0 0 36rpx;margin-left:20rpx;color:#78877f}.dot{width:54rpx;height:54rpx;border:2rpx solid #b6c6bc;border-radius:50%;text-align:center;line-height:50rpx;flex-shrink:0}.done,.active{color:#182b25}.done .dot{background:#17684b;color:#fff;border-color:#17684b}.active .dot{border:4rpx solid #17684b;color:#17684b}</style>
